{
  "headline": "Focus on clean indoor air and fitted N95 masks at {{level.name}} air quality",
  "summary": "Today's air sits at {{level.name}} with current US AQI {{aqi.now}}. Running filtration indoors delivers {{impact.diy_box_fan_filter.pct}} lower exposure, while your cleanest outdoor window is {{best.start}} to {{best.end}}.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Build a DIY box fan air filter",
      "why": "A simple, low-cost filter can significantly reduce indoor PM2.5, offering {{impact.diy_box_fan_filter.pct}} reduction.",
      "when": "Run continuously when indoors.",
      "steps": [
        "Use a MERV-13 filter or better.",
        "Seal filter edges to the fan with tape.",
        "Ensure good airflow and stable placement."
      ]
    },
    {
      "actionId": "child_play_indoors_when_poor",
      "title": "Keep children's play indoors",
      "why": "Reduces children's exposure to outdoor pollutants when air quality is {{level.name}}.",
      "when": "During periods of high pollution.",
      "steps": [
        "Set up indoor play areas.",
        "Engage children with indoor activities."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for no burning in the community",
      "why": "Community-wide efforts to stop burning can lower overall pollution levels, potentially by {{impact.community_no_burning.pct}}.",
      "when": "During high pollution seasons or events.",
      "steps": [
        "Talk to neighbors about the health impacts.",
        "Engage your Resident Welfare Association (RWA)."
      ]
    },
    {
      "actionId": "air_house_in_best_window",
      "title": "Ventilate your home during cleaner air windows",
      "why": "Bring in fresh air when outdoor levels are lowest, between {{best.start}} and {{best.end}}, to reduce indoor buildup.",
      "when": "During the best air quality windows.",
      "steps": [
        "Open windows on multiple sides for cross-ventilation.",
        "Close windows before pollution levels rise again."
      ]
    },
    {
      "actionId": "no_idling",
      "title": "Avoid unnecessary vehicle idling",
      "why": "Idling vehicles release harmful pollutants. Reducing idling can cut emissions and improve local air quality.",
      "when": "Whenever waiting in a vehicle.",
      "steps": [
        "Turn off the engine if waiting for more than a minute.",
        "Educate family members on the importance of not idling."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Keep children's outdoor play indoors while level remains {{level.name}}."
    },
    {
      "group": "adult",
      "note": "Consider reducing time spent near busy roads or idling vehicles."
    }
  ],
  "tradeoffs": [
    "Building a DIY filter requires effort but offers significant indoor air quality improvement."
  ]
}
